/**
 * 负责野孩子原槽创建／安装、宽只读查询、工具解析、选择／取消与转换数据写入和预期内容编码。
 * 输入为原数据绑定及生命周期已核参数；输出保持同一 raw 槽和原 expectedState 字符串，投影另作副本。
 * get 原本只取自有 data descriptor，不是完整 payload schema；不得借迁槽新增拒绝、冻结或复制 live 状态。
 * 榜样生命、阵营／Victory、时钟和已发布死亡事实仍归生命周期；槽数据和知识不是当前许可或档案协议。
 */
import type { WildChildState, WildChildReadState } from "@ai-werewolf-arena/game-contract";
import { copyEventData } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
export const WILD_CHILD_POLICY = "awa_lui_meme_wild_child_v1" as const;
export function freshWildChildState(): WildChildState {
  return {
    policy: WILD_CHILD_POLICY,
    remaining: 1,
    status: "pending",
    choice: null,
    eligibleNight: null,
    activeFromNight: null,
  };
}
export function getWildChildState(role: RoleComponent | undefined): WildChildReadState | undefined {
  const container = role && Object.getOwnPropertyDescriptor(role, "privateState");
  const value =
    container &&
    Object.hasOwn(container, "value") &&
    container.value &&
    Object.getOwnPropertyDescriptor(container.value, "wildChild");
  return value && Object.hasOwn(value, "value") ? (value.value as WildChildReadState) : undefined;
}
export function readWildChildTool(
  value: unknown,
): { name: "choose_wild_model"; args: { target_id: number } } | null {
  try {
    const p = copyEventData(value) as Record<string, unknown> | null;
    const args = p?.args as Record<string, unknown> | undefined;
    return p &&
      Object.keys(p).length === 2 &&
      p.name === "choose_wild_model" &&
      args &&
      Object.keys(args).length === 1 &&
      Number.isSafeInteger(args.target_id) &&
      (args.target_id as number) > 0
      ? { name: "choose_wild_model", args: { target_id: args.target_id as number } }
      : null;
  } catch {
    return null;
  }
}

import type { RoleInitializationComponent } from "../contracts";

/** 保原同引用查询、LHS 与 fresh callee 的先后；初始化不建立新的 World 或许可记录。 */
export function initializeWildChildState(role: RoleInitializationComponent): void {
  if (!getWildChildState(role)) role.privateState.wildChild = freshWildChildState();
}

/** 原内部内容证据编码：复制或 stringify 失败仍只返回 invalid，不是归档 schema 或授权。 */
export function encodeWildChildData(value: unknown): string {
  try {
    return JSON.stringify(copyEventData(value));
  } catch {
    return "invalid";
  }
}

import type { NightLifeScope } from "../../../../core/domain/night_effects";
/** 直接使用原 lifecycle 绑定字段，不新增 store、镜像或绑定类；model 仍是原捕获生命引用。 */
interface WildChildDataBinding {
  state: WildChildReadState;
  expectedState: string;
  model: NightLifeScope | null;
}

/** 先核原可写字段，再消费与写 choice；model 的延迟读取夹在写槽与编码之间。 */
export function commitWildChildState(
  b: WildChildDataBinding,
  choice: NonNullable<WildChildReadState["choice"]>,
  model: () => NightLifeScope,
): boolean {
  if (
    !["remaining", "status", "choice"].every(
      (k) => Object.getOwnPropertyDescriptor(b.state, k)?.writable,
    )
  )
    return false;
  (b.state as Pick<WildChildState, "remaining">).remaining = 0;
  (b.state as Pick<WildChildState, "status">).status = "chosen";
  (b.state as Pick<WildChildState, "choice">).choice = choice;
  b.model = model();
  b.expectedState = encodeWildChildData(b.state);
  return true;
}

/** lifecycle 先关闭原窗口；这里只执行原两字段可写短路及已写内容证据更新。 */
export function cancelWildChildState(b: Pick<WildChildDataBinding, "state" | "expectedState">): void {
  if (["remaining", "status"].every((k) => Object.getOwnPropertyDescriptor(b.state, k)?.writable)) {
    (b.state as Pick<WildChildState, "remaining">).remaining = 0;
    (b.state as Pick<WildChildState, "status">).status = "closed";
    b.expectedState = encodeWildChildData(b.state);
  }
}

/** 原榜样事实、阵营和 Victory 已经提交后才写转换数据；错误保留那些已发布前缀。 */
export function transformWildChildState(b: Pick<WildChildDataBinding, "state" | "expectedState">, day: number): void {
  (b.state as Pick<WildChildState, "status">).status = "transformed";
  (b.state as Pick<WildChildState, "eligibleNight">).eligibleNight = day + 1;
  b.expectedState = encodeWildChildData(b.state);
}

/** 原夜资格与活跃标记先由 lifecycle 处理；编码失败仍按原 invalid 结果继续，不补新的清理。 */
export function activateWildChildState(b: Pick<WildChildDataBinding, "state" | "expectedState">, day: number): void {
  (b.state as Pick<WildChildState, "status">).status = "active";
  (b.state as Pick<WildChildState, "activeFromNight">).activeFromNight = day;
  b.expectedState = encodeWildChildData(b.state);
}

/** 先在原点查询 owner；不当前只显示关闭副本，正常状态仍完整克隆原槽。 */
export function projectWildChildData(b: Pick<WildChildDataBinding, "state">, current: () => boolean): WildChildReadState {
  if (!current()) return { ...freshWildChildState(), remaining: 0, status: "closed" };
  return structuredClone(b.state);
}

/**
 * 单元测试负责核野孩子转换核心失败与晚事实失败的不同资格结果。输入为真实首夜选择、
 * 原榜样首死及测试自有安装／发表抛错；字面组件引用、写序、原错误和 owner 查询为预期。
 * 不变量：核心失败保已写前缀但字段恢复不复活本族许可；完整核心后的事实失败仍保转换。
 * 只调用本族死亡贡献，不执行中央死亡波、全周期或模型，不据此授予其它赠予能力权限。
 */
import { expect, test } from "bun:test";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import { Camp, COMPONENT, DeathCause, Phase, Role, type GameEvent } from "../../../../src/core";
import { GameActionRequestFactory } from "../../../../src/game/engine/action_request_factory";
import { ToolGateway } from "../../../../src/game/gateway/tool_gateway";
import {
  openWildChildNight,
  projectWildChild,
  recordWildChildDeathCommit,
  resolveWildChildDeathWave,
  validWildChildOwner,
  wildChildBinding,
  wildChildPackActive,
  wildChildPackKnown,
} from "../../../../src/game/mechanisms/roles/wild_child/lifecycle";
import { WildChildSetupWindow } from "../../../../src/game/mechanisms/roles/wild_child/setup";
import { foxBoard } from "../../../support/features/cursed-fox/builders/scenario";

/** 真实 setup 使用已绑定的 canonical 配置；榜样首死保原 Alive 对象／版本，不伪造生命周期绑定。 */
async function prepared() {
  const roles = [Role.WildChild, Role.Wolf, Role.Wolf, Role.Seer, Role.Witch, Role.Hunter];
  const game = bootstrapGame(foxBoard(roles), { fixedRoles: roles });
  const events: GameEvent[] = [];
  const result = await new WildChildSetupWindow(game.world, new ToolGateway(), events, {
    get requestFactory() { return GameActionRequestFactory; },
  }).execute(game.boardConfig, {
    async getAction() { return { name: "choose_wild_model", args: { target_id: 2 } }; },
  }, 1, () => true);
  if (!result) throw new Error("literal_wild_setup_expected_success");
  const binding = wildChildBinding(game.world)!;
  recordWildChildDeathCommit(game.world, 2);
  game.world.getComponent(2, COMPONENT.Alive)!.alive = false;
  return { ...game, events, binding };
}

const contribute = (g: Awaited<ReturnType<typeof prepared>>) =>
  resolveWildChildDeathWave(g.world, [2], { 2: [DeathCause.Poison] }, 1, Phase.Night, g.events);

test("Camp installation failure keeps its prefix and restoring duplicate fields cannot revive the Wild owner", async () => {
  const g = await prepared(), b = g.binding;
  const role = b.actor.role, camp = b.camp, victory = b.victory;
  const state = structuredClone(b.state), expected = b.expectedState;
  const error = new Error("literal_wild_camp_install_failure"), writes: string[] = [];
  const original = g.world.addComponent;
  // 仅测试实例拦截原安装点；正常调用保原 receiver，不新增生产 hook 或补偿。
  g.world.addComponent = new Proxy(original, {
    apply(target, receiver, args) {
      if (args[0] === 1 && args[1] === COMPONENT.Camp) {
        writes.push("Camp:throw");
        throw error;
      }
      return Reflect.apply(target, receiver, args);
    },
  });
  let caught: unknown;
  try { contribute(g); } catch (e) { caught = e; } finally { g.world.addComponent = original; }
  expect(caught).toBe(error);
  expect(writes).toEqual(["Camp:throw"]);
  expect(g.world.getComponent(1, COMPONENT.Role)).toBe(role);
  expect(role.camp).toBe(Camp.Wolf);
  expect(g.world.getComponent(1, COMPONENT.Camp)).toBe(camp);
  expect(camp.camp).toBe(Camp.Good);
  expect(g.world.getComponent(1, COMPONENT.Victory)).toBe(victory);
  expect(b.state).toEqual(state);
  expect(b.expectedState).toBe(expected);
  expect(b.modelCommitted).toBe(true);
  expect(g.events.map(e => e.type)).toEqual(["wild_child_model_chosen", "wild_child_model_eliminated"]);
  expect(validWildChildOwner(b)).toBe(false);
  role.camp = Camp.Good;
  expect(validWildChildOwner(b)).toBe(false);
  expect(projectWildChild(g.world, role)?.status).toBe("closed");
  expect(wildChildPackKnown(role, g.world)).toBe(false);
  expect(wildChildPackActive(role, g.world)).toBe(false);
  contribute(g);
  const close = openWildChildNight(g.world, 2, g.events);
  close();
  expect(b.state).toEqual(state);
  expect(g.events.map(e => e.type)).toEqual(["wild_child_model_chosen", "wild_child_model_eliminated"]);
});

test("Victory installation failure keeps installed Wolf Camp while retiring only the Wild transformation owner", async () => {
  const g = await prepared(), b = g.binding;
  const camp = b.camp, victory = b.victory, state = structuredClone(b.state);
  const error = new Error("literal_wild_victory_install_failure"), writes: string[] = [];
  const original = g.world.addComponent;
  g.world.addComponent = new Proxy(original, {
    apply(target, receiver, args) {
      if (args[0] === 1 && args[1] === COMPONENT.Camp) writes.push("Camp:installed");
      if (args[0] === 1 && args[1] === COMPONENT.Victory) {
        writes.push("Victory:throw");
        throw error;
      }
      return Reflect.apply(target, receiver, args);
    },
  });
  let caught: unknown;
  try { contribute(g); } catch (e) { caught = e; } finally { g.world.addComponent = original; }
  expect(caught).toBe(error);
  expect(writes).toEqual(["Camp:installed", "Victory:throw"]);
  expect(g.world.getComponent(1, COMPONENT.Camp)).not.toBe(camp);
  expect(g.world.getComponent(1, COMPONENT.Camp)?.camp).toBe(Camp.Wolf);
  expect(g.world.getComponent(1, COMPONENT.Victory)).toBe(victory);
  expect(victory.affiliations).toEqual([{ kind: "faction", faction: Camp.Good }]);
  expect(b.actor.role.camp).toBe(Camp.Wolf);
  expect(b.actor.camp).toBe(Camp.Good);
  expect(b.camp).toBe(camp);
  expect(b.state).toEqual(state);
  expect(validWildChildOwner(b)).toBe(false);
  // 恢复原组件和重复值仍不解锁失败标记；同值新引用的旧撤权规则没有在此改写。
  g.world.addComponent(1, COMPONENT.Camp, camp);
  b.actor.role.camp = Camp.Good;
  expect(validWildChildOwner(b)).toBe(false);
  expect(projectWildChild(g.world, b.actor.role)?.status).toBe("closed");
  expect(g.events.map(e => e.type)).toEqual(["wild_child_model_chosen", "wild_child_model_eliminated"]);
});

test("transformed fact publication failure preserves a fully committed owner and following-night pack activation", async () => {
  const g = await prepared(), b = g.binding;
  const error = new Error("literal_wild_transformed_fact_failure");
  const original = g.events.push;
  g.events.push = new Proxy(original, {
    apply(target, receiver, args) {
      if (args.some((event: GameEvent) => event.type === "wild_child_transformed")) throw error;
      return Reflect.apply(target, receiver, args);
    },
  });
  let caught: unknown;
  try { contribute(g); } catch (e) { caught = e; } finally { g.events.push = original; }
  expect(caught).toBe(error);
  expect(g.world.getComponent(1, COMPONENT.Camp)?.camp).toBe(Camp.Wolf);
  expect(g.world.getComponent(1, COMPONENT.Victory)?.affiliations).toEqual([{ kind: "faction", faction: Camp.Wolf }]);
  expect(b.state.status).toBe("transformed");
  expect(b.state.eligibleNight).toBe(2);
  expect(b.expectedState).toBe(JSON.stringify(b.state));
  expect(validWildChildOwner(b)).toBe(true);
  expect(projectWildChild(g.world, b.actor.role)?.status).toBe("transformed");
  expect(g.events.map(e => e.type)).toEqual(["wild_child_model_chosen", "wild_child_model_eliminated"]);
  contribute(g);
  const close = openWildChildNight(g.world, 2, g.events);
  close();
  expect(b.state.status).toBe("active");
  expect(wildChildPackKnown(b.actor.role, g.world)).toBe(true);
  expect(wildChildPackActive(b.actor.role, g.world)).toBe(true);
  expect(g.events.map(e => e.type)).toEqual(["wild_child_model_chosen", "wild_child_model_eliminated", "wild_child_pack_activated"]);
});

test("a frozen public binding does not replace the original Camp error while private failure revocation remains permanent", async () => {
  const g = await prepared(), b = g.binding;
  const camp = b.camp, error = new Error("literal_frozen_binding_camp_failure");
  expect(validWildChildOwner(b)).toBe(true);
  const original = g.world.addComponent;
  g.world.addComponent = new Proxy(original, {
    apply(target, receiver, args) {
      if (args[0] === 1 && args[1] === COMPONENT.Camp) {
        // 原 modelCommitted 已写；在实际安装调用内冻结绑定，再抛本例同一错误。
        Object.freeze(b);
        throw error;
      }
      return Reflect.apply(target, receiver, args);
    },
  });
  let caught: unknown;
  try { contribute(g); } catch (e) { caught = e; } finally { g.world.addComponent = original; }
  expect(caught).toBe(error);
  expect(Object.isFrozen(b)).toBe(true);
  expect(g.world.getComponent(1, COMPONENT.Camp)).toBe(camp);
  expect(b.actor.role.camp).toBe(Camp.Wolf);
  expect(validWildChildOwner(b)).toBe(false);
  b.actor.role.camp = Camp.Good;
  expect(validWildChildOwner(b)).toBe(false);
  expect(projectWildChild(g.world, b.actor.role)?.status).toBe("closed");
});

/**
 * 负责四族原生／学习死亡枪的数据创建、原槽安装、武装、捕获复验和库存消费。
 * 输入为原角色、原学习对象与晚取查询；输出保留同一槽／枪引用和原每次 hook 的捕获表。
 * 原生安装不克隆、不冻库存；学习模板仅创建自己的全新枪，已有整学习数据的复制仍由各族安装 owner 执行。
 * 本 owner 安装两个原生槽并写原枪字段，原体、生命、死因及请求许可仍在结算／具体权威复验；只读类型不是权限屏障。
 * 猎魔板子先捕获原审计库存，支付仍由同一权威执行；setter／编码或后续发表失败均不退款。
 */
import type {
  HunterState,
  HunterReadState,
  WolfKingState,
  WolfKingReadState,
  MechanicalReadState as MechanicalState,
  MechanicalReadLearning as MechanicalLearning,
  MechanicalReadSkill as MechanicalSkill,
  MechanicalReadState,
  AwakenedReadState as AwakenedState,
  AwakenedReadLearning as AwakenedLearning,
  AwakenedReadSkill as AwakenedSkill,
  AwakenedReadState,
} from "@ai-werewolf-arena/game-contract";
import { Camp, Role } from "../../../core/domain/model";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { World } from "../../../core/domain/world";
import type { RoleInitContext } from "./contracts";
import type { openDemonHunterStockFrame } from "./demon_hunter/native-gun-ports";

/** 创建仍逐次读取原配置 getter，不缓存 boardConfig／policy；分支保持原字段可选性。 */
export function createHunterState(ctx: Pick<RoleInitContext, "boardConfig">): HunterState {
  return {
    canShoot: true,
    ...(ctx.boardConfig?.hunter?.deathActionPolicy === "awa_knife_or_exile_v1"
      ? { deathActionPolicy: ctx.boardConfig.hunter.deathActionPolicy }
      : {}),
  };
}
export function createWolfKingState(ctx: Pick<RoleInitContext, "boardConfig">): WolfKingState {
  return {
    canShoot: true,
    ...(ctx.boardConfig?.wolfKing?.deathActionPolicy !== undefined &&
    ctx.boardConfig.wolfKing.deathActionPolicy !== "awa_qualified_sources_v1"
      ? { deathActionPolicy: ctx.boardConfig.wolfKing.deathActionPolicy }
      : {}),
  };
}

/** get 仍可调用原槽 getter；set 原左值赋入同对象，不新增 schema 或 descriptor 拒绝。 */
export function setHunterState(roleComp: RoleComponent, state: HunterState): HunterReadState {
  (roleComp.privateState as { hunter: HunterState })["hunter"] = state;
  return state;
}

export function getHunterState(roleComp: RoleComponent): HunterReadState | undefined {
  return (roleComp.privateState as { readonly hunter?: unknown })["hunter"] as
    HunterReadState | undefined;
}

export function setWolfKingState(roleComp: RoleComponent, state: WolfKingState): WolfKingReadState {
  (roleComp.privateState as { wolf_king: WolfKingState })["wolf_king"] = state;
  return state;
}

export function getWolfKingState(roleComp: RoleComponent): WolfKingReadState | undefined {
  return (roleComp.privateState as { readonly wolf_king?: unknown })["wolf_king"] as
    WolfKingReadState | undefined;
}

export type LearnedNativeGun = Extract<MechanicalSkill, { kind: "hunter" }>;
/** 学习得到新满库存模板，不从目标玩家复制已花费资源或原体许可。 */
export function createLearnedNativeGun(): { kind: "hunter"; canShoot: boolean; armed: boolean } {
  return { kind: "hunter", canShoot: true, armed: false };
}
/** 实际夜／激活检查仍由本族调用方先完成；只在原赋值点武装同一枪，不补偿其他字段。 */
function armLearnedNativeGun(gun: LearnedNativeGun): void {
  (gun as { armed: boolean }).armed = true;
}

/** 机械枪必须进入实际 ready 夜；保持 kind→ready→原 skill 左值读取，不因模式或查询补武装。 */
export function armMechanicalNativeGun(learned: MechanicalLearning, day: number): void {
  if (learned.skill.kind === "hunter" && day >= learned.readyOnNight)
    armLearnedNativeGun(learned.skill);
}
/** 觉醒枪仅在原整次激活通过后武装；activationNight／activeFromNight 仍在其后原点更新。 */
export function armAwakenedNativeGun(learned: AwakenedLearning): void {
  if (learned.skill.kind === "hunter") armLearnedNativeGun(learned.skill);
}

/** 生产每次 hook 独立持有原捕获表；这里不另验 World，换学习／原枪后返回 undefined。 */
export function createMechanicalGunReader(runtime: {
  readonly getMechanicalState: (role: RoleComponent | undefined) => MechanicalReadState | undefined;
}): (role: RoleComponent) => LearnedNativeGun | undefined {
  const owners = new Map<
    RoleComponent,
    {
      state: MechanicalState;
      learning: MechanicalLearning;
      gun: Extract<MechanicalSkill, { kind: "hunter" }>;
    }
  >();
  return (role) => {
    const query = runtime.getMechanicalState;
    const state = query(role),
      learning = state?.learned,
      skill = learning?.skill;
    if (role.camp !== Camp.Wolf || !state || !learning || skill?.kind !== "hunter" || !skill.armed)
      return undefined;
    const prior = owners.get(role);
    if (prior && (state !== prior.state || learning !== prior.learning || skill !== prior.gun))
      return undefined;
    if (!prior) owners.set(role, { state, learning, gun: skill });
    return skill;
  };
}

/** 生产每次 hook 独立持有原捕获表；这里不另验 World，换学习／原枪后返回 undefined。 */
export function createAwakenedGunReader(runtime: {
  readonly getAwakenedState: (role: RoleComponent | undefined) => AwakenedReadState | undefined;
}): (role: RoleComponent) => LearnedNativeGun | undefined {
  const owners = new Map<
    RoleComponent,
    {
      state: AwakenedState;
      learned: AwakenedLearning;
      gun: Extract<AwakenedSkill, { kind: "hunter" }>;
      targetId: number;
      role: AwakenedLearning["role"];
      day: number;
      activationNight: number;
      activeFromNight: number;
    }
  >();
  return (role) => {
    const query = runtime.getAwakenedState;
    const state = query(role),
      learned = state?.learned,
      gun = learned?.skill;
    if (
      role.camp !== Camp.Wolf ||
      !state ||
      !learned ||
      learned.role !== Role.Hunter ||
      learned.activationNight === null ||
      learned.activeFromNight === null ||
      gun?.kind !== "hunter" ||
      !gun.armed
    )
      return undefined;
    const prior = owners.get(role);
    if (
      prior &&
      (state !== prior.state ||
        learned !== prior.learned ||
        gun !== prior.gun ||
        learned.targetId !== prior.targetId ||
        learned.role !== prior.role ||
        learned.day !== prior.day ||
        learned.activationNight !== prior.activationNight ||
        learned.activeFromNight !== prior.activeFromNight)
    )
      return undefined;
    if (!prior)
      owners.set(role, {
        state,
        learned,
        gun,
        targetId: learned.targetId,
        role: learned.role,
        day: learned.day,
        activationNight: learned.activationNight,
        activeFromNight: learned.activeFromNight,
      });
    return gun;
  };
}

/** 晚取原猎魔命令；非 Hunter 分支不读命令，类型引用不会初始化 authority。 */
export interface NativeDeathGunStockQueries {
  readonly openHunterStock?: typeof openDemonHunterStockFrame;
}
export function captureNativeGunStock(
  kind: Role,
  queries: NativeDeathGunStockQueries,
  world: World,
  actorId: number,
  state: object,
): ReturnType<typeof openDemonHunterStockFrame> {
  if (kind !== "hunter") return null;
  const command = queries.openHunterStock!;
  return command(world, actorId, state);
}
/** 付款不补资格：原 stock 自验并写审计；普通分支只写原 canShoot。失败保原写入前缀。 */
export function consumeNativeDeathGun(
  state: { readonly canShoot: boolean },
  stock: ReturnType<typeof openDemonHunterStockFrame>,
): void {
  if (stock) stock.consume();
  else (state as { canShoot: boolean }).canShoot = false;
}

/**
 * 负责共用参与者的原生命、Role 与私有容器引用捕获和晚复验。输入为原 World／玩家 ID，
 * 输出保留原可写快照及当前性布尔值；不写 World、资源、阶段或领域许可。
 * 只复用原生命版本规则，Role 字段按原普通属性读取；getter／Proxy 可执行并按原时点抛错。
 * 不读取 Camp 组件、不校验枚举／JSON／完整槽、不建立 brand 或冻结快照；严格原体契约另有所有者。
 */
import { COMPONENT } from "./components/names";
import type { RoleComponent } from "./components/role";
import type { World } from "./world";
import { captureNightLife, livingNightLife, type NightLifeScope } from "./night_effects";

/** 保原可写顶层字段与组件引用；camp 是捕获的 Role.camp 值，不是 Camp 组件或独立行动权限。 */
export interface OriginalParticipant {
  life: NightLifeScope;
  role: RoleComponent;
  roleId: RoleComponent["role"];
  camp: RoleComponent["camp"];
  state: RoleComponent["privateState"];
}
/** 原生命先捕获，再查询 Role；仅两者存在才按 role→camp→privateState 读取，不复制或提前取字段。 */
export function captureOriginalParticipant(world: World, id: number): OriginalParticipant | null {
  const life = captureNightLife(world, id),
    role = world.getComponent(id, COMPONENT.Role);
  return life && role
    ? { life, role, roleId: role.role, camp: role.camp, state: role.privateState }
    : null;
}
/** 生命／版本先短路，再核同 Role 引用及原三个字段；不新增 descriptor、Camp 引用或状态内容检查。 */
export function sameOriginalParticipant(world: World, snapshot: OriginalParticipant): boolean {
  return (
    livingNightLife(world, snapshot.life) &&
    world.getComponent(snapshot.life.id, COMPONENT.Role) === snapshot.role &&
    snapshot.role.role === snapshot.roleId &&
    snapshot.role.camp === snapshot.camp &&
    snapshot.role.privateState === snapshot.state
  );
}
